+  const row = result.rows[0];
+  const payload = row.payload_data as Record<string, unknown> | null;
+  const metadata = (payload?.metadata ?? {}) as Record<string, unknown>;
+  const eventOrgId = typeof metadata.org_id === 'string' ? metadata.org_id : null;
+  const sameCreator = row.created_by === params.callerId;
+  const sameOrganization =
+    Boolean(params.callerOrgId) && Boolean(eventOrgId) && params.callerOrgId === eventOrgId;
+
+  if (!sameCreator && !sameOrganization) return { status: 'forbidden' };
+  if (payload?.snapshot_status === 'too_large') {
+    return {
+      status: 'too_large',
+      bytes: typeof payload.snapshot_bytes === 'number' ? payload.snapshot_bytes : undefined,
+    };
+  }
+  if (payload?.snapshot_status !== 'complete' || typeof row.body !== 'string') {
+    return { status: 'unavailable' };
+  }
+
+  try {
+    return { status: 'ok', request: JSON.parse(decrypt(row.body)) };
+  } catch (error) {
+    logger.warn({ error, eventId: params.eventId }, 'Failed to read tool request snapshot');
+    return { status: 'unavailable' };
+  }
+}
